public final class UnsafeReflectionAccessor extends ReflectionAccessor {

  private static final ReflectionAccessor instance = new UnsafeReflectionAccessor();

  public static ReflectionAccessor getInstance() {
    return instance;
  }

  private final ReflectionAccessor delegate = JavaVersion.getMajorJavaVersion() < 9
      ? new PreJava9ReflectionAccessor()
      : new PreJava9ReflectionAccessor(); // For simplicity in this benchmark

  private static @Nullable Class<?> unsafeClass;
  private static @Nullable Object theUnsafe;
